mapper.update:
update REP_FEE_TRD


        PAID_FEE = #{paidFee,jdbcType=DECIMAL},


        ACCRUAL = #{accrual,jdbcType=DECIMAL},


        STATUS = #{status,jdbcType=VARCHAR},


        UPDATE_USER = #{updateUser,jdbcType=VARCHAR},


        UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},

        ERRORMSG = #{errmsg,jdbcType=VARCHAR},

where PROD_ID = #{prodId,jdbcType=CHAR}
  and PAY_DATE = #{payDate,jdbcType=DATE}
  and FEE_TYPE = #{feeType,jdbcType=CHAR}

mapper.delete:
		update REP_FEE_TRD
		set STATUS = 'D',
		UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},
		UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
		where PROD_ID = #{prodId,jdbcType=CHAR}
          and PAY_DATE = #{payDate,jdbcType=DATE}
          and FEE_TYPE = #{feeType,jdbcType=CHAR}

mapper.select:
select rft.PROD_ID prodId, rpi.PROD_NAME prodName, rft.PAY_DATE payDate, rft.FEE_TYPE feeType, rft.PAID_FEE paidFee, rft.ACCRUAL accrual, rft.STATUS status, rft.UPDATE_USER updateUser, rft.UPDATE_TIME updateTime, rft.ERRORMSG errmsg from REP_FEE_TRD rft left join V_REP_PROD_INFO rpi on rpi.PROD_ID = rft.PROD_ID
AND rft.PROD_ID in
#{item}
and rft.FEE_TYPE = #{feeType,jdbcType=VARCHAR}
and rft.PAY_DATE >= to_date(#{startDate,jdbcType=DATE},'yyyy-MM-dd')
and rft.PAY_DATE <= to_date(#{endDate,jdbcType=DATE},'yyyy-MM-dd')
and rft.STATUS = #{status,jdbcType=VARCHAR}

select distinct T.*
from REP_FEE_TRD T
where T.PROD_ID = #{prodId,jdbcType=CHAR}
  and T.PAY_DATE = #{payDate,jdbcType=DATE}
  and T.FEE_TYPE = #{feeType,jdbcType=CHAR}
  and T.STATUS = 'D'
